"""Standalone inspection of the actual DAG, learned search and archived PPA."""
from __future__ import annotations
import html
import json
from pathlib import Path
from .report import write_json
from .tangram_seed import dag_snapshot


def write_search_report(folder, workload, result, rows, accounting):
    folder=Path(folder)
    data={'dag':dag_snapshot(workload),'search':result.to_dict(),'rows':rows,'accounting':accounting}
    write_json(folder/'search_view.json',data)
    payload=json.dumps(data,ensure_ascii=False,default=str).replace('<','\\u003c')
    title=html.escape(workload.name)
    page='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>RL 搜尋與模型 DAG</title><style>body{font:15px system-ui,"Microsoft JhengHei",sans-serif;background:#f3f6fc;color:#20314a;margin:0;padding:28px}main{max-width:1300px;margin:auto}section{background:white;border:1px solid #dce4ef;border-radius:12px;padding:22px;margin:18px 0}h1{font-size:26px}h2{font-size:19px}p{line-height:1.7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}pre{white-space:pre-wrap;max-height:420px;overflow:auto;font:12px monospace}svg{width:100%;height:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:12px;text-align:left;border-bottom:1px solid #e3e9f1}button,select{padding:8px;border:1px solid #bdcbe0;border-radius:6px;background:white;color:#20314a}a{color:#4b57b8}small{color:#64758b}.scroll{overflow:auto}.graph{min-width:850px}.cards{display:flex;gap:12px;flex-wrap:wrap}.cards div{padding:14px;background:#eef3fb;border-radius:9px;min-width:160px}.cards b{display:block;font-size:22px}@media(max-width:850px){.grid{grid-template-columns:1fr}body{padding:14px}}</style>
<main><small>INMIN / GEMINI 2×2 CORE / SEARCH EVIDENCE</small><h1>TITLE：最佳可行方案與探索過程</h1>
<p>每個 compute chiplet 固定四個 cores。Tangram 式 DP/beam 產生起點，RL 依候選的穩定特徵選擇原子或複合動作，以同一個完整 evaluator 驗證。以下結果只代表本次模板與預算內找到的方案。</p>
<section><h2>執行與成本記帳</h2><div class="cards" id="cards"></div><pre id="accounting"></pre></section>
<section><h2>已探索架構的最佳方案</h2><div class="scroll"><table><thead><tr><th>架構</th><th>Compute / IO / DRAM</th><th>Latency</th><th>Power</th><th>Area</th><th>Energy</th><th>限制</th><th>部署</th></tr></thead><tbody id="rows"></tbody></table></div></section>
<section><h2>搜尋曲線</h2><p><small>目前探索成本與最佳可行成本分開保存；無可行 archive 的步驟不補造最佳值。</small></p><div id="curve"></div></section>
<section><h2>模型 DAG 與原始依賴</h2><p><small>每條 tensor 依賴均保留；點節點查看形狀和算子資料。Add 的所有輸入都會顯示。</small></p><div class="scroll" id="dag"></div><pre id="node"></pre></section>
<div class="grid"><section><h2>動作與交易紀錄</h2><label>步驟 <select id="step"></select></label><pre id="details"></pre></section><section><h2>診斷與支援能力</h2><pre id="capabilities"></pre><p><a href="joint_search.json">完整 RL JSON</a> · <a href="seed.json">Tangram 起點與來源</a> · <a href="workload.json">模型 DAG JSON</a></p></section></div>
<p><small>功率為相同 batch 推論時間窗的平均 E/T。所有 PPA 為未經 RTL 或 silicon 校準的分析估算；unsupported 的能力不會以效率係數替代。</small></p></main>
<script>const data=PAYLOAD;const $=id=>document.getElementById(id);const s=data.search;const fmt=(v,scale=1,d=3)=>v==null?'—':(v*scale).toFixed(d);
for(const [label,value]of [['模型層數',data.dag.nodes?.length??data.dag.layers?.length??0],['RL 完整評估',data.accounting.rl_unique_full_evaluations],['Policy 更新',s.policy_updates??0],['狀態',s.status]]){const d=document.createElement('div');d.append(document.createTextNode(label));const b=document.createElement('b');b.textContent=value;d.append(b);$('cards').append(d)}$('accounting').textContent=JSON.stringify(data.accounting,null,2);
for(const row of data.rows){const tr=document.createElement('tr'),m=row.metrics,r=row.hardware_resources;for(const text of [row.architecture,`${r.compute_dies} / ${r.io_dies} / ${r.memory_dies}`,fmt(m.latency_s,1000)+' ms',fmt(m.power_w)+' W',fmt(m.area_mm2,1,2)+' mm²',fmt(m.energy_j,1000)+' mJ',row.within_limits?'符合硬限制':'超出硬限制']){const td=document.createElement('td');td.textContent=text;tr.append(td)}const td=document.createElement('td'),a=document.createElement('a');a.href=row.architecture+'/layout.html';a.textContent='檢視 cores 與流量';td.append(a);tr.append(td);$('rows').append(tr)}
const trace=s.trace||[];function lineChart(){const vals=trace.map((t,i)=>({x:i,y:t.current_cost??t.cost??t.new_cost??t.penalized_cost,b:t.best_cost}));const finite=vals.flatMap(t=>[t.y,t.b]).filter(Number.isFinite);if(!finite.length){$('curve').textContent='此預算沒有可繪製的 transition 成本，完整資料見 RL JSON。';return}const lo=Math.min(...finite),hi=Math.max(...finite,lo+1e-6),w=1080,h=250;const px=i=>50+i*(w-80)/Math.max(1,vals.length-1),py=v=>h-30-(v-lo)*(h-60)/(hi-lo);const path=key=>vals.filter(t=>Number.isFinite(t[key])).map(t=>`${px(t.x)},${py(t[key])}`).join(' ');$('curve').innerHTML=`<svg viewBox="0 0 ${w} ${h}"><line x1="50" y1="20" x2="50" y2="220" stroke="#8190a5"/><line x1="50" y1="220" x2="1050" y2="220" stroke="#8190a5"/><polyline points="${path('y')}" fill="none" stroke="#9aabca" stroke-width="2"/><polyline points="${path('b')}" fill="none" stroke="#6250c4" stroke-width="3"/><text x="65" y="20" font-size="12">灰：目前方案　紫：最佳可行方案　步數 ${vals.length}</text><text x="5" y="35" font-size="11">${hi.toFixed(3)}</text><text x="5" y="215" font-size="11">${lo.toFixed(3)}</text></svg>`}lineChart();
trace.forEach((t,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${i+1} · ${t.family_id??t.plan?.family_id??t.action_plan?.family_id??t.realized_action_plan?.family_id??'transition'} · reward ${fmt(t.reward)}`;$('step').append(o)});function step(){$('details').textContent=JSON.stringify(trace[Number($('step').value)]||{},null,2)}$('step').onchange=step;step();$('capabilities').textContent=JSON.stringify({capabilities:s.capabilities??s.capability_matrix??null,initial_diagnostics:s.initial_metrics?.diagnostics??null},null,2);
const inputNodes=(data.dag.tensors||[]).filter(t=>t.is_model_input).map(t=>({...t,id:'tensor:'+t.id,label:t.id,operator:'Input'}));const nodes=[...inputNodes,...(data.dag.nodes||data.dag.layers||[])],edges=data.dag.edges||[];const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');const cols=Math.min(6,Math.max(1,nodes.length)),rows=Math.ceil(nodes.length/cols),width=cols*185+20,height=rows*95+30;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.classList.add('graph');const positions=new Map(nodes.map((n,i)=>[n.id??n.layer_id,{x:15+(i%cols)*185,y:15+Math.floor(i/cols)*95}]));for(const edge of edges){const from=edge.producer??edge.source??edge.from??('tensor:'+edge.tensor_id),to=edge.consumer??edge.target??edge.to;const a=positions.get(from),b=positions.get(to);if(!a||!b)continue;const line=document.createElementNS(ns,'path');line.setAttribute('d',`M${a.x+80} ${a.y+50} L${b.x+80} ${b.y}`);line.setAttribute('stroke','#90a6bd');line.setAttribute('fill','none');svg.append(line)}nodes.forEach((n,i)=>{const p=positions.get(n.id??n.layer_id),g=document.createElementNS(ns,'g'),rect=document.createElementNS(ns,'rect'),label=document.createElementNS(ns,'text');rect.setAttribute('x',p.x);rect.setAttribute('y',p.y);rect.setAttribute('width',160);rect.setAttribute('height',50);rect.setAttribute('rx',7);rect.setAttribute('fill',(n.operator??n.kind??n.op)==='Add'?'#fff0c4':'#e6eefb');rect.setAttribute('stroke','#8fa5be');label.setAttribute('x',p.x+8);label.setAttribute('y',p.y+29);label.setAttribute('font-size',11);label.textContent=(n.label??n.id??n.layer_id??i).slice(0,23);g.style.cursor='pointer';g.onclick=()=>{$('node').textContent=JSON.stringify(n,null,2)};g.append(rect,label);svg.append(g)});$('dag').append(svg);</script></html>'''
    (folder/'report.html').write_text(page.replace('TITLE',title).replace('PAYLOAD',payload),encoding='utf-8')
